import java.util.Scanner;

enum DivideStatus { OK, DIVIDE_BY_ZERO, OVERFLOW }

record DivideResult(DivideStatus status, int value) {}

class Harness {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextInt()) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            DivideResult result = Solution.safeDivide(a, b);
            switch (result.status()) {
                case OK:
                    System.out.println("OK " + result.value());
                    break;
                case DIVIDE_BY_ZERO:
                    System.out.println("DIVIDE_BY_ZERO");
                    break;
                case OVERFLOW:
                    System.out.println("OVERFLOW");
                    break;
            }
        }
    }
}

